using System.Collections.Generic;

namespace PKHeX.Modern.Services;

public sealed record HelpItem(string Title, string Text, string Shortcut = "");

public sealed record HelpSection(string Icon, string Title, IReadOnlyList<HelpItem> Items);

/// <summary>
/// Conteudo da pagina Ajuda › Funções.
/// IMPORTANTE: ao adicionar ou mudar uma funcao do app, atualize esta lista (e a secao "Próxima versão" do CHANGELOG.md).
/// </summary>
public static class HelpContent
{
    public static IReadOnlyList<HelpSection> Sections { get; } =
    [
        new("💾", "Saves",
        [
            new("Abrir um save", "Clique em “Abrir save...”, arraste o arquivo para a janela ou passe o caminho pela linha de comando. Sem save aberto, a barra lateral lista os saves da pasta do Save Manager em “Seus saves” (um clique abre) e “↺ Último” reabre o save anterior; para fazer isso sozinho, marque “Abrir último save ao iniciar” no ⚙ da barra lateral.", "Ctrl+O"),
            new("Vários saves em abas", "Cada save aberto vira uma aba no topo, com o selo do jogo e ● quando tem alterações não salvas. Trocar de aba não perde nada: cada save guarda as alterações, o desfazer/refazer, a caixa e a página. Abrir um save que já está numa aba só troca para ela. “+” vai para o Save Manager; ✕ fecha a aba (pergunta se houver alterações).", "Ctrl+Tab / Ctrl+W"),
            new("Tela inicial", "Ao abrir um save, o app mostra o Início (⌂ na barra lateral, Ctrl+0): o cartão do jogo com treinador, tempo de jogo, dinheiro e Pokédex; a equipe no topo (clique abre na página Equipe); um atalho grande para cada página, com um resumo; e os saves recentes, que abrem numa aba nova.", "Ctrl+0"),
            new("Status do save no Início", "Abaixo do cartão do jogo, o Início mostra a situação do save: as alterações ainda não salvas (clique para ver a lista e salvar), a data do último backup (clique para abrir a lista de backups), as vagas livres nas caixas e o nome do arquivo (passe o mouse para ver o caminho)."),
            new("Save Manager", "Tela inicial e página Saves: lista os saves da pasta escolhida (subpastas como gba, ds, 3ds e switch viram grupos), com treinador, TID/SID, tempo de jogo, dinheiro, capturados e equipe. Busca por jogo, treinador ou arquivo e filtro por geração. Duplo clique abre.", "Ctrl+9"),
            new("Detalhes e teclado no Save Manager", "Os cartões mostram o idioma identificado pelo PKHeX e o início da aventura quando o jogo guarda uma data disponível. Clique num cartão ou use Tab para dar foco; as setas navegam entre cartões e Enter abre o selecionado. “Esconder SID” oculta esse dado e mantém a preferência nas próximas aberturas. O resumo informa arquivos que não foram reconhecidos como saves, inclusive em pastas sem saves válidos."),
            new("Saves dentro de .zip", "Backups do JKSV (ou qualquer .zip com saves) na pasta de saves aparecem no Save Manager com o selo ZIP, um cartão por save lá dentro. Também dá para abrir um .zip direto. Ao salvar, o app oferece gravar de volta dentro do zip (o zip inteiro ganha um backup antes) ou salvar como arquivo separado."),
            new("Selo do jogo", "Cada save mostra o Pokémon da capa nas cores da versão (Ho-Oh no HeartGold, Rayquaza no Emerald...), no Save Manager e no cartão do save aberto na barra lateral."),
            new("Versão dos saves antigos", "Saves da Gen 1–3 não guardam qual jogo do par são (Red/Blue, Gold/Silver, Ruby/Sapphire, FireRed/LeafGreen) nem o idioma ocidental. O app descobre pelo nome do arquivo, da entrada do zip, do zip ou da pasta (“Pokemon Ruby”, “Rouge”, “Rot”, “azul”, “LeafGreen”...). Sem pista, mostra o par, como “Ruby / Sapphire”, com o selo duplo (os dois mascotes)."),
            new("Salvar", "“💾 Salvar” grava direto por cima do arquivo do save, sem abrir janela; antes, o arquivo anterior é copiado para os backups. “Salvar como...” (Ctrl+E) escolhe outro lugar.", "Ctrl+S"),
            new("Alterações não salvas", "O aviso na barra lateral mostra quantas alterações ainda não foram salvas; clique nele para ver a lista. O app pergunta antes de abrir outro save ou fechar."),
            new("Backups", "No Save Manager, o botão “Backups” lista as cópias automáticas. “Restaurar” volta o backup para o arquivo de origem (o arquivo atual ganha um backup antes); “Restaurar como...” grava em outro lugar."),
            new("Conferência dos backups", "Cada cópia nova guarda motivo, jogo, tamanho e SHA-256 num registro, sem treinador. A lista mostra o motivo e avisa se o hash mudou; Restaurar pergunta antes de continuar com uma cópia alterada. Backups antigos continuam disponíveis com motivo desconhecido. O limite de 20 também remove os registros. No Android, as cópias privadas recebem o mesmo registro."),
        ]),
        new("📦", "Caixas e equipe",
        [
            new("Relatório das caixas", "Em Caixas, “⋯ Caixa › Exportar relatório (CSV)” exporta equipe e todas as caixas do save aberto, com dados, IVs, EVs, golpes e legalidade. Escolha onde salvar pelo seletor do sistema; no Android, use o seletor de documentos. O relatório abre no Excel e no Google Sheets e não altera o save."),
            new("Creche", "Na página Equipe, a creche mostra os Pokémon depositados. Clique para editar e use Aplicar para gravar de volta. Pôr na creche move o Pokémon selecionado das caixas ou da equipe; Tirar da creche leva ao primeiro espaço livre das caixas. Essas operações têm desfazer. Ovo pronto, seed e experiência aparecem onde o Core oferece suporte. SW/SH mostra as duas creches e a seed; não expõe a flag de ovo pronto. As alterações vão para o arquivo com Salvar."),
            new("Caixas em pasta", "Na página Caixas, o botão ⋯ exporta esta caixa ou todas, com subpastas opcionais. A importação lê arquivos de Pokémon e Mystery Gifts, inclusive subpastas, converte para o jogo e mostra os recusados. Escolha a caixa inicial, limpeza e substituição; operações destrutivas pedem confirmação. O modo legal oferece legalizar o lote uma vez. A importação inteira é um passo de desfazer. No Android, as pastas são lidas e gravadas pelo seletor. Arquivos existentes não são substituídos na exportação."),
            new("Barra inferior contextual", "Os botões da barra inferior acompanham a página: ações de Pokémon em Caixas/Equipe; Abrir e Atualizar em Saves; Usar encontro/evento nos bancos; Atualizar anexados no Bank; Atualizar e Sincronizar na Pokédex; Aplicar mochila nos itens. Salvar permanece disponível nas páginas do save aberto. Ajuda mostra Voltar; os atalhos existentes continuam funcionando."),
            new("Importar Mystery Gift", "Solte um arquivo de evento (.wc*, .pgf, .pcd e outros formatos do PKHeX) num slot da caixa ou da equipe do save ativo, ou use Importar. O Pokémon é gerado para o save, com confirmação antes de substituir e Ctrl+Z para desfazer. Um presente de itens não pode gerar Pokémon no slot."),
            new("Salvar uma edição pendente", "Salvar, Ctrl+S e Salvar como também aplicam a edição pendente do Pokémon e os itens mudados na Mochila antes de gravar. Se o modo legal impedir Aplicar, o salvamento é bloqueado e mostra o motivo: corrija ou descarte a edição. Falhas de gravação mostram uma janela e mantêm as alterações na memória."),
            new("Nome e papel de parede", "Na página Caixas, abra o menu “⋯ Caixa” para renomear a caixa atual e escolher o papel de parede. O limite de caracteres e as opções dependem do jogo; jogos sem suporte escondem os controles. As alterações ficam na aba do save e são gravadas com Salvar. O fundo aparece discretamente atrás dos cartões, ou nítido como no jogo com a opção “Inteiro” do ⚙."),
            new("Telas vazias", "Quando não há nada para mostrar (pasta de saves vazia, nenhum backup, caixa vazia, nenhum outro save aberto no Bank, Pesquisa sem resultado, Hall da Fama vazio), a tela mostra um desenho simples e a dica do que fazer. Na caixa vazia, o aviso não atrapalha: dá para arrastar Pokémon para os slots e clicar neles normalmente."),
            new("Linha do tempo do save", "O Início mostra a linha do tempo do save: a cada abertura, o app compara com a vez anterior e lista o que mudou (horas de jogo, Pokémon e espécies novas, shinies com o sprite, insígnias, Pokédex e dinheiro). “No jogo” é o que mudou jogando; “Salvo no app” é o que você gravou aqui. Na primeira vez, se houver backup do save, ele vira o ponto de partida. Os resumos ficam na pasta de dados do app, sem mexer no save."),
            new("Ficha do Pokémon", "O topo do editor é a ficha do Pokémon: sprite, nome, gênero e shiny, os tipos (e o Tera no Scarlet/Violet), o nível com a natureza, a bola de captura e o selo do jogo de origem com a geração, sobre o brilho da cor dos tipos. Tudo acompanha as edições na hora, antes de Aplicar."),
            new("Bola de captura", "A bola de captura aparece na ficha do Pokémon, no topo do editor: clique nela para ir à aba Encontro, com a lista de bolas já em foco. Na lista, cada bola aparece com o seu sprite. No modo legal, só as bolas possíveis para aquele Pokémon aparecem."),
            new("Cartões", "Cada slot mostra sprite, nome, nível, gênero, bola, ★ shiny e ✓/⚠ de legalidade. Passe o mouse para ver o resumo (set, encontro, PID e o primeiro problema de legalidade). As caixas ficam em abas no topo.", "Ctrl+1 / Ctrl+2"),
            new("Hexágono de atributos", "Na aba Atributos do editor, o hexágono mostra os seis atributos no estilo de Sword/Shield e Scarlet/Violet: a forma na cor do primeiro tipo, os EVs como segunda camada dourada e o valor de cada atributo junto do nome. O nome fica vermelho no atributo que a natureza aumenta e azul no que ela diminui. Muda na hora ao editar nível, IVs, EVs ou natureza."),
            new("Vitrine da equipe", "Na página Equipe, “🖼 Vitrine” mostra os Pokémon da equipe grandes, com tipos, Tera (Scarlet/Violet), item, habilidade, natureza e golpes nas cores dos tipos. Escolha Grade (3×2) ou Colunas (os seis lado a lado) e use “Salvar imagem” para gravar um PNG em alta resolução, pronto para compartilhar. A imagem leva só a vitrine, com o nome do treinador e o jogo. Esc ou Fechar volta."),
            new("Equipe Showdown", "O botão “📋 Showdown” da Equipe e o menu “⋯ Caixa” das Caixas colam vários sets de uma vez (o texto do Teambuilder do Showdown ou de um PokéPaste, separados por linha em branco) nas vagas da equipe ou nos slots vazios da caixa atual. Antes, uma lista mostra cada set: ✓ legal, ⚠ ilegal (só com o modo legal desligado) ou ✗ fora, com o motivo; no modo legal, um set ilegal é gerado de novo a partir de um encontro do jogo. Colar é um único Ctrl+Z. “Copiar” leva a equipe ou a caixa inteira para a área de transferência no formato Showdown."),
            new("Arrastar e soltar", "Arraste para mover (num slot ocupado, troca). Com Ctrl ou Shift copia; com Alt sobrescreve o destino e deixa a origem vazia. Durante o arraste, o sprite segue o ponteiro (no celular, acima do dedo) com o que vai acontecer ao soltar (Mover, Trocar, Copiar, Sobrescrever) e quantos vão juntos; a origem fica apagada até soltar."),
            new("Seleção múltipla", "Ctrl+clique marca vários, Shift+clique marca um intervalo e Ctrl+A marca a caixa toda. Arraste o grupo para outra caixa ou para o bank, ou exclua todos com Delete. Esc desmarca.", "Ctrl+A"),
            new("Travar caixa", "Em “⋯ Caixa”, “🔒 Travar caixa” protege a caixa aberta: arrastar para dentro ou para fora, excluir, aplicar o editor, colar Showdown, edição em lote, fábrica de ovos e Living Dex são recusados enquanto ela estiver travada, com um aviso na barra de status. “Ordenar todas as caixas” pula as travadas. A aba mostra um cadeado e a trava fica salva para aquele arquivo de save. Desfazer continua funcionando."),
            new("Ordenar caixas", "Botão “⇅ Ordenar”: por Pokédex, nome, nível, shiny, tipo, IVs ou data de captura, na caixa aberta ou em todas."),
            new("Desfazer e refazer", "Mover, copiar, importar, ordenar, excluir e aplicar no editor podem ser desfeitos.", "Ctrl+Z / Ctrl+Y"),
            new("Busca global", "Procura espécie, apelido, golpe ou item em todas as caixas e na equipe. Também aceita “shiny” e “ovo”. Clique num resultado para ir até ele.", "Ctrl+F"),
            new("Importar, exportar, criar e excluir", "Barra inferior: Importar um arquivo .pk* (ou solte o arquivo num slot), Exportar PKM do slot selecionado, Criar PKM no primeiro slot vazio e Excluir.", "Del"),
            new("Verificar legalidade", "Confere o save inteiro em segundo plano e mostra a lista de problemas, com atalho para o primeiro."),
        ]),
        new("✏️", "Editor de Pokémon",
        [
            new("QR da Gen 7", "O botão QR no editor de Sun/Moon/Ultra mostra um código para o QR Scanner do jogo, que registra a espécie na Pokédex. Salvar imagem exporta um PNG, também pelo seletor Android. Os cartões da Gen 6/7 têm QR no formato de arquivo do PKHeX; esse código não entrega o evento pelo QR Scanner. Gerar QR não altera o save."),
            new("Cartões de evento no save", "Jogo → Cartões lista os presentes armazenados no save. Em Eventos, selecione um cartão e use Adicionar ao save para recebê-lo dentro do jogo; também há importação, exportação, exclusão e marcar como não recebido. Na Gen 4, PCD e PGT são ligados e o entregador é ativado; HeartGold/SoulSilver têm o espaço especial da Lock Capsule. Let's Go guarda apenas registros WR7, sem entregas pendentes. Exclusão e flags podem ser desfeitas na página Jogo. Salvar grava as alterações."),
            new("Hidden Power", "Na aba Atributos (Gen 2–7), o tipo e o poder acompanham os IVs. Escolher um tipo usa o método do PKHeX para ajustar os IVs. O modo legal preserva os IVs se o resultado seria ilegal e bloqueia encontros com PID e IVs ligados na Gen 3/4. Na aba Golpes, Hidden Power mostra seu tipo calculado."),
            new("Pokérus", "Na aba Extras, escolha Sem Pokérus, Infectado ou Curado. Dar Pokérus aplica uma cepa válida com a duração máxima. Avançado permite ajustar cepa e dias dentro dos limites do jogo. O modo legal bloqueia Pokémon que não podem ter Pokérus. Aplicar altera o save em memória; Salvar grava o arquivo."),
            new("Evolução assistida", "Na Visão geral, Evoluir reúne os resultados disponíveis neste jogo. Cada linha mostra o requisito e o motivo quando está bloqueada. Escolher abre uma prévia; confirmar deixa a edição pendente até Aplicar. O app ajusta nível, felicidade e Beauty quando necessário, remove a Everstone e registra a troca. Requisitos de local, horário e equipe são explicados sem mudar o mundo do save. O modo legal bloqueia resultados ilegais; Aplicar pode ser desfeito."),
            new("Feebas: beleza ou troca", "Feebas evolui para Milotic por Beauty, não por felicidade. Quando o jogo permite, a Visão geral oferece evoluir: o botão sobe o Beauty até o mínimo (170), ajusta o Sheen à faixa legal onde ele acompanha os atributos, tira a Everstone e sobe um nível. Nos jogos sem concursos, o Beauty só pode subir se o Pokémon veio de um jogo que tem concursos. BDSP oferece Beauty; Z-A oferece troca. A troca pode ser simulada mesmo sem Prism Scale; se estiver segurando a escala, ela será consumida. No modo legal, o resultado só substitui a edição após validar uma cópia. Aplicar ou Salvar grava a evolução."),
            new("Abas", "Visão geral, Atributos, Golpes, Encontro, Treinador e Extras. A aba aberta continua a mesma ao trocar de slot. “Aplicar alterações” grava a edição no save em memória; Salvar também aplica a edição pendente antes de gravar o arquivo."),
            new("Busca enquanto digita", "Espécie e item mostram a lista inteira ao tocar ou clicar, com o nome atual selecionado; ao digitar, a lista filtra por qualquer parte do nome (ex.: chu acha Pichu, Pikachu e Raichu). Os golpes têm sugestões, e os que o Pokémon aprende aparecem em verde, no topo da lista."),
            new("Descrições em português", "Golpes, habilidades e itens mostram a descrição em português da geração do save (passe o mouse; nos golpes, ela aparece embaixo). Os textos vêm do AllGenWiki."),
            new("Habilidade, forma e Tera Type", "Escolhidos em listas na Visão geral. A habilidade oculta aparece marcada; a forma só lista as que existem no jogo; o Tera Type (Scarlet/Violet) funciona como as Tera Shards."),
            new("Extras", "PID e EC editáveis em hexadecimal (valem ao sair do campo), marcações ●▲■♥★◆ (na Gen 7+ cada clique alterna azul → rosa → nenhuma) e Tornar shiny."),
            new("Hyper Training", "Na aba Atributos (Gen 7+): marca o atributo como treinado, contando como IV 31. Exige nível 100 (50 em Scarlet/Violet)."),
            new("Fitas e memórias", "Aba própria: todas as fitas do formato, com busca, “Só as que tem”, “Todas as legais” (as que o Pokémon pode ter pela história dele) e “Remover todas”; memórias do treinador original e do atual (Gen 6+), com detalhe, intensidade e sentimento."),
            new("Contest stats e especiais", "Na aba Extras: Cool, Beauty, Cute, Smart, Tough e Sheen (no modo legal, o Sheen acompanha os atributos sozinho, como com Pokéblocks/Poffins, e a seção some nos jogos sem concursos); felicidade (a partir da Gen 2); Dynamax Level e Gigantamax (Sword/Shield); alpha e nobre (Legends)."),
            new("Onde aprender", "Passe o mouse num golpe (no campo ou na lista) para ver onde aprendê-lo neste jogo: o local da TM e o tutor, quando houver (AllGenWiki)."),
            new("Legalidade e correções", "O cartão de legalidade lista os problemas e oferece correções de um clique: golpes sugeridos, golpes de reaprender, encontro sugerido e IVs máximos. Na Gen 3/4, se IVs 31 forem impossíveis no encontro atual (IVs ligados ao PID), o app oferece converter em nascido de ovo. Um apelido que o jogo não aceita é trocado pelo nome da espécie ao legalizar. Avisos (“Fishy”) de valores livres, como EVs zerados depois de subir de nível ou EXP exatamente no limite do nível, são corrigidos pelo Legalizar sem trocar o encontro. No modo legal, uma correção que deixaria o Pokémon ilegal não é aplicada e o motivo aparece na barra de status."),
            new("Legalizar ao clicar", "Ao clicar num Pokémon ilegal das caixas ou da equipe, o app pergunta se você quer legalizá-lo. “Legalizar” gera o Pokémon de novo a partir de um encontro real do jogo (mantendo natureza, nível, item, apelido e golpes quando possível) e já grava no slot; Ctrl+Z desfaz. “Só abrir” abre no editor como antes, e o app não pergunta de novo sobre esse Pokémon até fechar o app. Avisos (Fishy) não disparam a pergunta. Para não perguntar nunca, desmarque “Oferecer legalizar ao clicar num ilegal” no ⚙; o botão Legalizar do editor continua disponível."),
            new("✨ Legalizar", "Gera o Pokémon de novo a partir de um encontro real do jogo (PID/IV corretos, inclusive shiny), mantendo natureza, nível, item, apelido e golpes quando possível."),
            new("Set do Showdown legal", "No modo legal, “Colar Showdown” no editor e a colagem de vários sets transformam um set ilegal num Pokémon legal deste jogo: o app procura um encontro real gerando com os IVs, a habilidade, a natureza, o gênero e o shiny do set e reaplica nível, item, apelido, golpes (com o registro de TM/TR em Sword/Shield e Scarlet/Violet), EVs, amizade e Tera Type. Quando o jogo permite, usa Hyper Training para os IVs, menta para a natureza e cápsula/patch para a habilidade. Entre os resultados legais fica o mais parecido com o set, e a mensagem diz o que não deu para manter (ex.: “não deu para manter: IVs”). Se a espécie não existe no jogo ou não há forma legal, o set fica de fora com o motivo."),
            new("Showdown", "“Colar Showdown” importa um set da área de transferência; “Copiar Showdown” exporta o Pokémon."),
            new("Forma e gênero", "A forma é escolhida numa lista com o sprite de cada forma. Clique no ♂/♀ ao lado do nome para trocar o gênero (até a Gen 5 isso gera outro PID, com a mesma natureza). No Meowstic, Indeedee, Basculegion e Oinkologne a forma é o gênero: trocar um troca o outro. Na Gen 3, a forma do Deoxys depende do jogo."),
            new("Natureza e shiny (Gen 3/4)", "Da Gen 3 e 4, a natureza vem do PID: trocar a natureza sorteava outro PID e o shiny se perdia. Agora, num shiny, o app procura um PID com a natureza nova que continue shiny, com o mesmo gênero e a mesma habilidade. No modo legal, o Pokémon é gerado de novo a partir de um encontro real com a natureza nova (o PID precisa casar com os IVs pelo método do jogo), mantendo o shiny; se não houver forma legal, a mudança é desfeita."),
            new("Atalhos de shiny", "Clique na estrela ao lado do nome (ou em “Tornar shiny”, na aba Extras): torna shiny ou tira o shiny. Alt+clique: shiny mantendo o PID (troca o SID do treinador; mantém a ligação PID/IV da Gen 3/4). Shift+clique: shiny quadrado; Ctrl+clique: shiny estrela (diferença só a partir da Gen 8).", "Alt / Shift / Ctrl"),
        ]),
        new("🛡", "Modo legal",
        [
            new("Modo Hardcore", "Para desafios (como o Nuzlocke) e RetroAchievements: no ⚙, “Modo Hardcore (só mover Pokémon)” desliga toda edição de dados. O editor só mostra os dados; criar, copiar, importar, colar Showdown, legalizar, gerar encontros e eventos, aplicar a Living Dex e completar ou sincronizar a Pokédex ficam desligados; Treinador, Mochila, Jogo e Edição em lote saem da barra lateral. Mover, trocar, soltar, ordenar, levar para o Bank e trazer de volta continuam, com Ctrl+Z. O cartão “Modo Hardcore” fica no lugar do modo legal; clique nele para desligar."),
            new("O que faz", "Cartão na barra lateral (verde = ligado, âmbar = desligado; clique para alternar), ligado por padrão. O editor só oferece opções legais (golpes que o Pokémon aprende, bolas permitidas para o encontro, espécies do jogo) e desfaz na hora qualquer mudança que deixaria o Pokémon ilegal, explicando o motivo."),
            new("Opções legais", "Habilidade e Tera Type só listam o que o encontro permite; formas de batalha somem da lista. Na Gen 3–5 a habilidade vem do PID: para trocar, use ✨ Legalizar."),
            new("Trocar encontro", "Na aba Encontro, local e nível ficam travados: escolha um encontro real deste jogo na lista “Trocar encontro” e o Pokémon é gerado de novo a partir dele, mantendo natureza, nível, item, apelido e golpes quando possível."),
            new("Shiny", "“Tornar shiny” fica bloqueado quando o encontro nunca é shiny (shiny lock). Nos outros, o Pokémon é gerado de novo já shiny, com PID/IV corretos."),
            new("Aplicar só legal", "Um Pokémon ilegal não pode ser aplicado; use ✨ Legalizar ou as correções sugeridas. Trocar a espécie, a forma ou colar um set Showdown legaliza sozinho."),
            new("Pokémon de fora", "Arquivo .pk*, bank ou outro save: se chegar ilegal ao save aberto, o app oferece “✨ Legalizar” ou “Trazer como está”."),
            new("Prévia de alterações", "Antes de legalizar ou transferir entre gerações, confira os valores antes e depois. ⚠ marca mudanças importantes. A confirmação aplica exatamente o candidato exibido; cancelar preserva o Pokémon. Transferências em lote mostram o resumo por campo e a lista completa. O save só muda em memória até Salvar, com desfazer nos slots."),
            new("Legalidade por assunto", "O editor reúne problemas e avisos em grupos com gravidade e contagem. O primeiro grupo inválido abre sozinho. Golpes, Bola, Fitas e Encontro oferecem as correções existentes; Legalizar mostra a prévia antes de mudar. Grupos sem correção segura mostram somente os motivos."),
            new("Desligado", "Vale qualquer valor, como no PKHeX clássico. Use com cuidado."),
        ]),
        new("🏦", "Bank",
        [
            new("Relatório do Bank", "No Bank, CSV exporta todas as caixas do banco escolhido, no formato original de cada Pokémon. A consulta de legalidade não troca o save aberto. O arquivo usa UTF-8 com BOM, com cabeçalhos no idioma da interface e nomes do jogo em inglês. Os arquivos do Bank permanecem intactos."),
            new("Consulta do Bank", "Toque num Pokémon para consultar seus dados, IVs, EVs, golpes e legalidade sem alterar o Bank. O painel permite exportar, copiar Showdown, ver variantes e abrir uma cópia no editor quando o save aceita o formato. Aplicar essa cópia usa um slot vazio do save; o original do Bank permanece preservado."),
            new("Bancos e caixas", "Armazenamento próprio, fora dos saves, em bancos → caixas (crie, renomeie, ordene e exclua). Os Pokémon ficam como arquivos .pk* no formato original.", "Ctrl+3"),
            new("Duas telas", "Bank à esquerda e save aberto à direita: arraste entre os dois. Ao trazer para o save, o Pokémon é convertido para a geração do jogo."),
            new("Outro save", "Troque o painel esquerdo para “💾 Outro save” e mova Pokémon entre dois jogos (com conversão). Seleção múltipla funciona nos dois lados; o outro save tem ↶/↷ próprios no painel. Clique em “Salvar este save” para gravar."),
            new("Pokémon anexado", "Com “🔗 Anexar ao trazer” ligado, levar um Pokémon do bank para um save copia em vez de mover: o original fica no bank com o selo 🔗. Depois de jogar, “Atualizar anexados” traz a versão do jogo (nível, golpes, evolução) de volta para o bank; se o jogo for de outra geração, ela fica guardada como variante e o original não muda. Os que sumiram do save podem ser desanexados."),
            new("Variantes", "Clique num Pokémon anexado (🔗) do bank para ver, embaixo da grade, as versões que voltaram de jogos de outra geração. “✎ Abrir no editor” leva a variante escolhida para o save aberto (convertida, se precisar), no lugar da cópia anexada ou num slot vazio da caixa; ao Aplicar, o anexado passa a apontar para este save. “🗑” apaga só a variante; o original do bank não muda."),
            new("Pastas externas", "“📁+” transforma qualquer pasta com arquivos .pk* (ex.: a do PKHeX) num banco, sem mover os arquivos."),
        ]),
        new("📖", "Pokédex",
        [
            new("Auditoria de duplicados", "Em Pesquisa, Duplicados mostra cópias com o mesmo tipo de arquivo e os mesmos dados armazenados, byte a byte. Backups ficam agrupados por par de arquivos: cópias dentro de ZIP e saves que compartilham muitos Pokémon iguais (como as pastas de “main” do Switch copiadas por data). Anexados e variantes registrados no Bank têm etiqueta própria; Comparar aparece quando seus dados diferem. Abra um grupo e use Ir ao local. A consulta não exclui, legaliza nem organiza Pokémon. Cancelar descarta a leitura incompleta; alterações exigem atualizar."),
            new("Pesquisa em todos os saves", "A página 🔎 Pesquisa (Ctrl+Shift+F) junta numa lista os Pokémon de todos os saves abertos (com as alterações ainda não salvas), dos saves da pasta do Save Manager (inclusive dentro de .zip) e do bank. Busque por espécie, apelido, golpe, item, habilidade, natureza, bola, treinador ou jogo; todas as palavras precisam bater (ex.: “garchomp earthquake shiny”; “#25” busca pelo número). Filtre por origem (um save ou banco), shiny, IVs perfeitos, natureza, bola, nível, geração de origem e ovos, e ordene por Pokédex, nível, IVs, nome ou lugar. Clique num resultado: no save aberto, vai até o slot; num save fechado, abre o save numa aba e vai até ele; no bank, abre a caixa.", "Ctrl+Shift+F"),
            new("Edição em lote", "A página ⚙ Edição em lote altera vários Pokémon do save aberto de uma vez. Escolha o grupo (caixa atual, todas as caixas, equipe, caixas e equipe, os selecionados com Ctrl+clique ou os resultados da Pesquisa deste save), marque ações rápidas (nível 100, IVs máximos, zerar EVs, felicidade máxima, curar, tornar shiny, golpes sugeridos, Pokébola legal e Legalizar, que gera de novo a partir de um encontro real os que ficarem ilegais) e/ou escreva o script do Batch Editor do PKHeX: “=Species=Pikachu” filtra, “!IsShiny=True” filtra o diferente, “.CurrentLevel=100” altera. “Pré-visualizar” mostra o que muda em cada Pokémon sem gravar; “Aplicar” pergunta antes e grava tudo num passo só (Ctrl+Z desfaz). Com o modo legal ligado, quem ficaria ilegal (⚠) é pulado."),
            new("Completar a Pokédex do save", "Na página Pokédex, “✔ Completar Pokédex do save” abre as opções para o save aberto: Completar (todas as espécies vistas e capturadas, com formas, gêneros e idiomas da Gen 4 em diante), Marcar todas como vistas, Tirar as capturadas e Limpar a Pokédex. Da Gen 5 em diante, “Incluir shiny” marca também as formas shiny como vistas. Cada opção pergunta antes, tem Ctrl+Z na própria página e só vai para o arquivo com Salvar. Útil para o Shiny Charm, o Oval Charm e os diplomas. Em Sword/Shield, Scarlet/Violet, BD/SP e Z-A, vale a Pokédex regional de cada jogo; Legends: Arceus guarda pesquisa por tarefas e fica de fora (o PKHeX também não tem esse atalho para ele)."),
            new("Caçada shiny", "A página ✨ Caçada shiny (no fim da barra lateral) ajuda na caçada: escolha a espécie e o método do jogo aberto (encontro comum, Masuda, Poké Radar, pesca em corrente, Friend Safari, SOS, Catch Combo, Dynamax Adventure, surtos e sanduíche...) e conte cada encontro com +1, Espaço ou + (− desfaz; dá para somar vários). Ela mostra a chance por encontro, a chance de já ter achado, quantos encontros faltam para 50%, 90% e 99% (com a curva), o tempo caçando e o ritmo por hora. O Shiny Charm vem marcado se estiver na mochila do save. “Onde encontrar” lista os locais e níveis do jogo, avisa do shiny lock e dos golpes do selvagem que podem estragar a caçada (Explosion, Roar, Teleport, Perish Song, recuo...), com o que fazer. Ao abrir um save com um shiny novo da espécie, o app oferece concluir a caçada. A caçada fica guardada no computador; o save não muda."),
            new("Fases e troféus da caçada", "Saiu um shiny que não era o alvo? “✨ Registrar fase” guarda o encontro em que ele apareceu (e a espécie, que dá para escolher depois na lista de fases) sem zerar a caçada. Ao abrir um save, um shiny novo de outra espécie também é oferecido como fase. Quando o alvo aparece e você conclui, a caçada vira um troféu: espécie, jogo, método, encontros, fases, data e onde ele está no save, com “Ir” para abrir o Pokémon. “Nova caçada” mantém os troféus (e pergunta antes de apagar uma caçada com encontros). “Exportar CSV” salva troféus, a caçada atual e as fases numa planilha."),
            new("Fábrica de ovos", "Na Pokédex, sem espécie escolhida, “🥚 Ovos das que faltam” gera um ovo legal para cada espécie que falta no save aberto (da forma básica: um ovo de Charmander para o Charizard que falta, um de Pichu para o Pikachu) e “🥚 Um ovo de cada família” gera um de cada família que nasce de ovo no jogo. Os ovos vêm dos ovos de criação do próprio jogo, com o seu treinador, e vão para as vagas livres das caixas a partir da caixa aberta. A lista aparece antes de gravar, um Ctrl+Z desfaz tudo e Salvar grava no arquivo. Lendários e Pokémon que só existem em eventos ficam de fora. Da Gen 2 em diante; desligado no modo Hardcore."),
            new("Relatório de Nuzlocke", "Na Pokédex › Nuzlocke, o save aberto vira um relatório: o primeiro Pokémon capturado em cada rota (pelo local que o jogo guarda; da Gen 4 em diante, pela data de captura), as capturas a mais na mesma rota, os repetidos (família já capturada numa rota anterior) e quem está na equipe, vivo nas caixas ou morto. Escolha a caixa do cemitério (uma caixa com “Cemitério”, “Grave” ou “Dead” no nome já vem escolhida). Pokémon de trocas, de outros jogos e ovos ficam de fora. “Copiar relatório” copia em texto para fórum ou rede social; “Ir” abre o Pokémon. A Gen 1 e a Gen 2 (menos o Crystal) não guardam o local de captura."),
            new("Resumo da coleção", "Sem nenhuma espécie escolhida, o painel da direita mostra barras de Living dex, Shiny dex, capturadas e vistas, e quantas espécies faltam em cada geração (clique numa geração para listar só as que faltam). “Próxima que falta” escolhe a próxima espécie que você ainda não tem; “‹ Resumo” volta para o resumo. Tudo segue os filtros de fonte e tipo."),
            new("Pokédex centralizada", "Junta a Pokédex de todos os saves da pasta, o save aberto (inclusive alterações não salvas) e o bank. Mostra o que você possui, o que foi capturado ou visto em cada jogo e os shiny.", "Ctrl+4"),
            new("Living dex e filtros", "Resumo de living dex e shiny dex; filtros por situação (faltando, shiny, alpha...), geração, tipo e fonte. “Formas e gêneros” mostra cada forma como entrada própria."),
            new("Aplicar a Living Dex", "Na Living Dex, escolha a primeira caixa e se deseja reservar posições para faltantes. Prévia da aplicação usa o save aberto como destino real, mostra cada movimento, cópia e realocação e bloqueia falta de espaço. Candidatos da equipe são preservados; os de fora são copiados, com o original intacto. Aplicar usa exatamente o resultado mostrado, com um único desfazer; se uma origem mudar, refaça a prévia. Salvar grava o arquivo."),
            new("Planejador de Living Dex", "Na Pokédex › Living Dex, escolha o jogo alvo, formas, shiny e fontes (saves abertos, pasta de saves, Bank). Gere um plano em ordem nacional, com o número de slots por caixa do jogo alvo (30; 20 na Gen 1/2). O melhor candidato prioriza legalidade, origem no jogo alvo e nível; os demais da mesma espécie aparecem como outros exemplares (não são cópias idênticas). Faltantes têm um botão para Encontros. A leitura mostra progresso e o plano não grava arquivos nem move Pokémon."),
            new("Onde está", "Selecione uma espécie para ver onde estão os seus; “Ir” abre o Pokémon no editor."),
            new("Só o save aberto", "Mostra só a Pokédex do save aberto: o que ele viu, capturou e tem guardado nas caixas e na equipe, sem misturar com os outros saves nem com o bank. Clique de novo para voltar a juntar tudo. É o mesmo que escolher o save aberto na lista de fontes."),
            new("Sincronizar", "Marca na Pokédex do save aberto o que foi capturado nos outros saves e o que você tem guardado. “Sincronizar todos os saves” faz o mesmo em cada save da pasta (os fechados são gravados na hora, com backup)."),
            new("Formas", "Em Gen 4, Gen 5, Gen 6, Sword/Shield, BDSP, Legends Arceus, Scarlet/Violet e Legends Z-A a Pokédex guarda cada forma: em “Formas e gêneros”, uma forma só conta como vista/capturada se aquele jogo a registrou. Nos outros jogos vale o dado da espécie (a Gen 7 e Let's Go guardam só a forma exibida, não as vistas)."),
        ]),
        new("🎒", "Treinador e mochila",
        [
            new("Roupas de Scarlet/Violet", "Jogo → Roupas em Scarlet/Violet lista o catálogo de liberação do PKHeX por categoria e gênero. Busque pelo nome da categoria em inglês ou ID; marque para liberar e desmarque para bloquear. O Core não fornece os nomes comerciais das peças, então a lista mostra categoria e ID. Liberar todas e Liberar todas desta categoria pedem confirmação e têm um passo de desfazer. A busca não limita a operação em massa. Salvar grava o arquivo."),
            new("Donuts de Z-A", "Jogo → Donuts lista tipos, estrelas, sabores e poderes em inglês. Edite as frutas, recalcule estrelas e use Aplicar donut. Gerar usa um efeito escolhido e o modelo do PKHeX. Duplicar e apagar alteram a bolsa; Encher substitui os 999 espaços após confirmação. Todas as operações têm desfazer. Salvar grava o arquivo."),
            new("Battle Frontier", "Jogo → Battle Frontier em Emerald, Platinum, HeartGold/SoulSilver (e a Battle Tower de Diamond/Pearl): BP, Frontier Pass e símbolos (prata/ouro) no Emerald, impressões de cada instalação na Gen 4 e as sequências de cada instalação, modo e nível (atual, recorde, trocas da Factory, CP do Castle, campeonatos do Dome), com a série em andamento. Na Battle Tower da Gen 4, mudar a sequência atual ajusta também as séries de 7 que o jogo guarda. Tudo tem desfazer; Salvar grava o arquivo."),
            new("Pokétch e Pokéwalker", "Jogo → Pokétch (Diamond/Pearl/Platinum) libera ou bloqueia cada aplicativo e escolhe o que aparece na tela; “Liberar todos” acerta também a contagem que o jogo guarda. Jogo → Pokéwalker (HeartGold/SoulSilver) edita watts, passos e as rotas liberadas; “Liberar todas” libera as rotas que existem no idioma do save. Tudo tem desfazer; Salvar grava o arquivo."),
            new("Medalhas do Pokéathlon", "Jogo → Pokéathlon (HeartGold/SoulSilver) mostra as 493 espécies com as cinco medalhas (Speed, Power, Skill, Stamina, Jump). Marque cada medalha ou “Todas” na linha; busque por nome ou número e filtre as incompletas. “Todas as medalhas” e “Tirar todas” valem para todas as espécies. Tudo tem desfazer; Salvar grava o arquivo."),
            new("Base secreta", "Jogo → Base secreta. Em Ruby/Sapphire/Emerald, lista a sua base e as que vieram de outros jogadores: edite nome, gênero, TID/SID, visitas, batalha de hoje e registro, e veja a equipe que defende a base. Em Omega Ruby/Alpha Sapphire, edita os textos da sua base (nome, equipe, lema e frases), o nível e as bandeiras, dá todas as decorações e apaga bases de outros jogadores (com confirmação). Tudo tem desfazer; Salvar grava o arquivo."),
            new("Pokémon errantes", "Jogo → Errantes edita o errante de Ruby/Sapphire/Emerald/FireRed/LeafGreen e a ave de X/Y. Na Gen 3, ajuste os dados e use Aplicar errante; Gerar dados legais usa um encontro real para PID e IVs. Fazer reaparecer reativa; em X/Y, reinicia a contagem. O modo legal exige espécie, nível e PID/IVs compatíveis, e a ave de X/Y corresponde ao inicial escolhido. Ruby/Sapphire/FireRed/LeafGreen têm o bug que trunca os IVs na captura; a tela mostra o resultado. O Core não expõe um local atual para editar. As alterações têm desfazer e só vão ao arquivo com Salvar."),
            new("Relógio da Gen 3", "Jogo → Relógio aparece em Ruby, Sapphire e Emerald. Edite dias, horas, minutos e segundos dos relógios inicial e decorrido. Corrigir relógio parado aplica a correção do PKHeX, avançando o decorrido para pelo menos 734 dias; Avançar 1 dia ajuda nos eventos diários. A hora do aparelho não muda. Cada alteração pode ser desfeita na página Jogo. Salvar grava o arquivo."),
            new("Desfazer na página Jogo", "Na página Jogo, ↶/↷ desfazem e refazem flags, valores, recordes, atalhos, Hall da Fama, cartões e raids. Nas outras páginas, esses botões continuam com os slots. A dica mostra qual ação será desfeita. Operações em massa contam como um passo; são guardados até 30 passos e 64 MB de diferenças. Trocar ou reabrir um save limpa o histórico do jogo. Salvar continua gravando as alterações no arquivo."),
            new("Raids", "Jogo → Raids permite editar Galar, Isle of Armor e Crown Tundra em Sword/Shield; Paldea, Kitakami e Blueberry Academy em Scarlet/Violet. Altere seed hexadecimal, tipo e flags de Watts ou League Points. Sword/Shield permite escolher 1–5 estrelas e o sorteio; em Scarlet/Violet, as estrelas dependem da seed e do progresso, e o tipo mostra a faixa. Os registros de 7 estrelas controlam captura e vitória. Ativar/desativar todas pede confirmação, preserva posições vazias e a toca especial. Não há busca de seed por Pokémon. Os botões ↶/↷ permitem desfazer. Salvar grava o arquivo."),
            new("Treinador: insígnias, gênero, moedas, BP e datas", "A página Treinador edita, além de nome, TID/SID, dinheiro e tempo de jogo: o gênero (Gen 2 no Crystal e da Gen 3 em diante); as insígnias de cada região, com “Todas” e “Nenhuma” (Gen 1 a 6, Sword/Shield e BD/SP; Gold/Silver/Crystal e HeartGold/SoulSilver têm Johto e Kanto); as moedas do Game Corner (Gen 1 a 4); os Battle Points (Emerald, Gen 4 a 7 e Sword/Shield); e, na Gen 4 e 5, as datas de início da aventura e de entrada no Hall da Fama. As alterações valem na hora; Salvar grava o arquivo."),
            new("Treinador", "Nome, TID/SID, dinheiro e tempo de jogo do save, com o estado dos checksums."),
            new("Mochila", "Itens por bolso, em colunas: cada slot é um cartão com o ícone, o item e a quantidade. Passe o mouse para ver a descrição em português e onde conseguir (dados do AllGenWiki); nas TMs/TRs/HMs, o golpe que ensinam e onde pegar a máquina. Troque o item e a quantidade e clique em “Aplicar mochila”; Salvar grava o arquivo. A mochila mostra os itens que você tem e algumas vagas livres para adicionar; “Mostrar todas as vagas” mostra o bolso inteiro."),
            new("Encher bolso", "Na Mochila, “◎ Encher bolso” tem conjuntos prontos: todos os TMs (com os HMs/TRs do mesmo bolso), todas as Poké Balls, todos os remédios (Gen 4 em diante) e todas as berries do jogo, além de “Tudo no bolso aberto”. Os itens entram com 99 de cada (1 nos HMs, nos TMs que não se gastam e em itens únicos), em ordem numérica, sem tirar o que já estava lá; o que não couber é avisado. Itens-chave ficam de fora, porque mexem no andamento do jogo. Depois, clique em “Aplicar mochila” e salve."),
            new("Atalhos de liberar tudo", "Jogo → Atalhos também libera de uma vez o que é chato de farmar: todos os O-Powers no nível máximo e todos os treinos do Super Training (X/Y e Omega Ruby/Alpha Sapphire), todas as Zygarde Cells com o contador atualizado (Sun/Moon e Ultra Sun/Ultra Moon), todos os itens do Grand Underground na quantidade máxima (BD/SP) e a bolsa de esferas do Underground cheia de esferas grandes (Diamond/Pearl/Platinum). Cada atalho tem desfazer; Salvar grava o arquivo."),
            new("Jogo: flags, valores, recordes, atalhos e Hall da Fama", "A página 🎮 Jogo edita o que o save guarda sobre o andamento do jogo. Flags de evento (Gen 1 a 7, Let's Go, BD/SP, Scarlet/Violet e Z-A): itens escondidos já pegos, treinadores vencidos, pontos de voo, eventos da história e outros, com os nomes que o PKHeX conhece; busque pelo nome, número (#120) ou código, filtre por categoria e use “Ativar mostradas” para ligar de uma vez tudo que o filtro mostra (ex.: categoria Voo). No Let's Go, o código diz o tipo (Z zona, S sistema, V objeto do mapa, E evento); no BD/SP, as flags de sistema aparecem como S#0000; no Scarlet/Violet, cada evento é um bloco do save (código hexadecimal); no Z-A, o jogo guarda só um hash por evento, então quase tudo aparece sem nome (os itens do mapa, como Colorful Screws e TMs, têm nome). Valores de evento: contadores e estados, com os valores conhecidos numa lista. Recordes (Gen 3, 5, 6, 7, Sword/Shield e BD/SP): passos, batalhas, ovos chocados... Atalhos: Pokémon fixos do mapa de novo (Gen 1: Mewtwo, aves lendárias, presentes...), títulos de Mestre Treinador (Let's Go), eventos do BD/SP (Darkrai, Shaymin, Arceus, errantes, mapa, roupas), Colorful Screws e TMs do mapa (Z-A), estojos cheios de Pokéblocks e Poffins (Ruby/Sapphire/Emerald, Diamond/Pearl/Platinum, Omega Ruby/Alpha Sapphire e BD/SP) e pontos, Data Cards e medalhas do Pokéathlon (HeartGold/SoulSilver). Hall da Fama (Gen 1, Gen 3, X/Y, Omega Ruby/Alpha Sapphire e Sun/Moon): as equipes que venceram a Liga. Clique num Pokémon para trocar espécie, apelido e nível (no Sun/Moon, só a espécie); no X/Y e no Omega Ruby/Alpha Sapphire também dá para mudar a data e o shiny. “Usar equipe atual” troca uma vitória pela equipe do save, “Apagar” tira a vitória e “Registrar equipe atual” adiciona a equipe do save como vitória nova, como ao vencer a Liga. As alterações valem na hora; Salvar grava o arquivo. Mudar flags de história fora de ordem pode travar eventos do jogo."),
        ]),
        new("🌿", "Encontros e eventos",
        [
            new("Banco de encontros", "Procura onde e como uma espécie aparece neste jogo. “Usar” gera o Pokémon legal e abre no editor."),
            new("Detalhes do encontro", "Clique num cartão para ver, ao lado, o que o encontro garante: shiny ou shiny lock (🔒), IVs, habilidade, natureza, gênero, bola, item, Tera Type, alpha/Gigantamax, treinador do evento e os golpes com que ele vem."),
            new("Filtros", "Depois da busca, filtre por tipo (selvagem, estático, troca, ovo, raid, evento, GO), por versão do jogo e por golpe (só os que já vêm com ele). Presentes do Pokémon HOME ganham o selo HOME."),
            new("Roamers da Gen 3", "Entei, Raikou e Suicune de FireRed/LeafGreen e Latias/Latios de Ruby/Sapphire têm um bug do jogo: só os 8 primeiros bits dos IVs são guardados, então o PS vai de 0 a 31, o Ataque de 0 a 7 e os outros ficam em 0. “Usar” sorteia esses valores como o jogo faz (antes saíam sempre zerados). IVs mais altos deixariam o Pokémon ilegal. Em Emerald não há o bug."),
            new("Eventos (Mystery Gift)", "Lista os presentes de evento que valem para o save, inclusive os da Gen 1 a 3. “Usar” leva ao editor."),
        ]),
        new("⌨️", "Atalhos",
        [
            new("Barra lateral em grupos", "As páginas ficam em quatro grupos (Pokémon, Treinador, Obter e Ferramentas), com ícones de traço que seguem a cor do tema. A ordem e os atalhos Ctrl+1 a Ctrl+9 continuam os mesmos."),
            new("Páginas", "Ctrl+0 vai para o Início; Ctrl+1 a Ctrl+9 vão para cada página; Q e E passam para a anterior/seguinte.", "Ctrl+0–9 · Q/E"),
            new("Ajuda", "Abre esta página; Esc ou “‹ Voltar” fecha.", "F1"),
            new("Paleta de comandos", "Ctrl+K (ou o ⌘ ao lado da busca) abre a paleta de comandos: digite o que quer fazer e Enter executa. Vale para ações (“legalizar”, “salvar”, “exportar”, “vitrine”, “tema”), páginas (“pokédex”, “mochila”), caixas pelo número ou nome (“caixa 5”) e Pokémon do save pela espécie ou apelido (“pikachu”), que abre o Pokémon no editor. Maiúsculas e acentos não importam. ↑↓ escolhem, Esc ou clicar fora fecha.", "Ctrl+K"),
            new("Voltar", "Esc desmarca a seleção, fecha o editor ou volta para Caixas.", "Esc"),
            new("Perguntas", "Enter confirma e Esc cancela.", "Enter / Esc"),
        ]),
        new("⚙️", "Preferências",
        [
            new("Prévia dos temas e papel de parede", "No ⚙, os cartões mostram miniaturas dos quatro temas renderizadas pelo próprio app, no modo claro ou escuro atual. Toque para aplicar. Papel de parede das caixas tem Normal, Suave, Desligado e Inteiro (o papel de parede do jogo nítido, com os cartões translúcidos por cima); a escolha fica salva e muda somente a exibição, sem alterar o papel de parede guardado no jogo."),
            new("Modo jogo", "No topo do ⚙, “🎮 Modo jogo” liga de uma vez a cor do jogo do save, o papel de parede inteiro das caixas, a cor do tipo nos cartões e as animações: o app fica com a cara do jogo aberto. Desligar volta ao visual de antes. Mudar uma dessas opções sozinha desliga o indicador, sem mexer nas outras. Também dá para ligar pela paleta de comandos (Ctrl+K)."),
            new("Barra lateral de Pokédex", "O topo da barra lateral é a tampa de uma Pokédex: a faixa na cor de destaque (com “Cor do jogo do save”, na cor do jogo aberto), a lente azul e as três luzes. Em cores claras, o nome fica escuro para continuar legível. A linha entre o topo e as páginas é a da Pokébola."),
            new("Ícones de jogo", "Os ícones da barra lateral e dos atalhos do Início são desenhos próprios com objetos dos jogos, cada um com a cor do objeto: Pokébola na Equipe, caixa do PC nas Caixas, o PC no Bank, a Pokédex, o treinador de boné, a mochila, o mato alto dos Encontros, o cartucho nos Saves e o portátil no Jogo."),
            new("Títulos em Fredoka", "Nos temas com a Inter, os títulos grandes (nome da página, do save e do Pokémon no editor, o logo e a vitrine da equipe) usam a Fredoka, uma fonte arredondada; o resto do texto continua na Inter. Para deixar tudo na Inter, escolha ⚙ › Fonte › Inter. No tema Pixel e nas outras fontes do ⚙, os títulos seguem a fonte escolhida."),
            new("Cor do jogo do save", "Na cor de destaque do ⚙, a bolinha em arco-íris é “Cor do jogo do save”: o destaque passa a seguir a versão aberta (vermelho no Scarlet, azul no Sapphire, rosa no Shining Pearl...), com um brilho suave da mesma cor no alto da tela. Ao trocar de aba, a cor troca junto; sem save aberto, volta ao vermelho. Cores muito claras ou muito escuras são ajustadas para os botões continuarem legíveis."),
            new("Animações", "Animações curtas dão retorno do que acontece: a Pokébola abre no centro da tela ao carregar um save, o cartão dá um pulinho quando o slot recebe um Pokémon (arrastar, colar, aplicar), sai um brilho ✦ do sprite no editor quando o Pokémon fica legal ou vira shiny, e a ★ dos shiny nas caixas pisca de vez em quando. Nenhuma bloqueia cliques. Para desligar todas (e economizar bateria no celular), desmarque “Animações” no ⚙."),
            new("Cor do tipo nos cartões", "Cada Pokémon das caixas, da equipe, do bank e do outro save tem o fundo do cartão tingido com a cor dos tipos dele: o primeiro tipo no canto de cima e o segundo no de baixo. Ovos e slots vazios ficam neutros. Para voltar aos cartões lisos, desmarque “Cor do tipo nos cartões” no ⚙."),
            new("Tamanho dos sprites", "No ⚙, “Tamanho dos sprites” deixa os Pokémon menores ou maiores nas caixas, no bank, no outro save e na Pokédex (Pequeno, Normal, Grande ou Enorme). Muda na hora e fica salvo; em telas grandes ou no celular, Grande e Enorme ajudam a reconhecer cada Pokémon."),
            new("Temas e cor", "Na linha de baixo da barra lateral: ◐ troca claro/escuro e ⚙ abre as preferências: o tema completo (Padrão, PSS de X/Y, Pixel de GBA, Z-A de Lumiose, Pokédex de ORAS ou Pokédex clássica de Kanto), que muda fundo, painéis, cantos, bordas e fonte na hora e aplica a cor de destaque sugerida pelo tema; a fonte (a do tema ou uma fixa, como Inter, Pixelify Sans ou Pokémon GB/GBC, em qualquer tema; legendas pequenas ficam sempre na Inter, e a Pokémon GB/GBC, que é larga, só vale nos títulos); as bolinhas da cor de destaque; o idioma (vale ao reiniciar) “Abrir último save ao iniciar” e “Oferecer legalizar ao clicar num ilegal”. ⌨ mostra os atalhos do teclado."),
            new("Idioma da interface", "No ⚙ da barra lateral, em Idioma, escolha Português (Brasil) ou English. A preferência fica salva e o app oferece reiniciar para aplicar. Nomes do jogo (espécies, golpes, itens) e os textos de legalidade do PKHeX continuam em inglês nos dois idiomas."),
            new("Atualização automática", "Ao abrir, o app verifica se saiu uma versão nova no GitHub. Se saiu, mostra as notas da versão: “Atualizar agora” baixa e instala conferindo o arquivo; “Depois” mantém o aviso para atualizar mais tarde. A oferta automática pode ser desligada em Ajuda › Sobre. A versão nova vale ao clicar em “🔄 Reiniciar” ou na próxima abertura; antes de reiniciar, o app pergunta se houver alterações não salvas e reabre o save. Rodando pelo código, a janela oferece abrir o download no navegador. Nos pacotes publicados, escolhe o download de Windows, Linux ou macOS e da arquitetura; no macOS troca o app inteiro, e no Linux restaura a permissão de execução. A pasta de instalação precisa permitir gravação."),
            new("Compartilhar diagnóstico", "Em Ajuda › Sobre, revise o diagnóstico antes de compartilhar no Android ou copiar no desktop. Ele inclui versão, sistema, idioma, tema, contagens da pasta de saves e as últimas 50 linhas do registro. Mensagens livres, nomes de arquivos e dados privados são omitidos; ficam os tipos de erro e as chamadas da pilha."),
            new("Arquivos do app", "Preferências, backups e bank ficam na pasta de dados do app: %APPDATA%\\PKHeX.Modern no Windows e ~/.config/PKHeX.Modern no Linux e no macOS. Se algo der errado, os detalhes ficam em crash.log, na mesma pasta."),
        ]),
        new("📱", "Android",
        [
            new("Selecionar e arrastar por toque", "Nas caixas e no Bank, toque em “☐ Selecionar” para marcar vários slots sem teclado. Um toque longo também liga a seleção; sair do modo limpa as marcas. Com o grupo marcado, escolha a caixa de destino, envie ao Bank, exclua ou abra a Edição em lote. O modo Mover/Copiar/Sobrescrever vale para o arraste; mantenha o dedo parado antes de arrastar para não confundir com rolagem. Toque e segure um botão para ver o que ele faz, sem executá-lo; nos temas e no modo de arraste há também um ⓘ."),
            new("Gestos", "Nas caixas, deslize o dedo para a esquerda para ir à próxima caixa e para a direita para voltar, como virar páginas. Vale na página Caixas e nos três painéis do Bank (cada um troca a própria caixa). Precisa ser um movimento rápido para o lado: segurar o dedo continua marcando e arrastando, e rolar para cima ou para baixo continua rolando. Na página Saves, puxe a lista para baixo para reler a pasta (ou os backups)."),
            new("Saves dos emuladores", "No Android, “🎮 Saves dos emuladores” na página Saves acha sozinho os saves do RetroArch, DraStic, melonDS, Dolphin, Azahar, Citra, Lime3DS, Eden/Yuzu (e derivados), mGBA, My Boy! e Pizza Boy nas pastas padrão de cada um, e também os saves (.sav, .srm, .dsv) ao lado das ROMs nas suas pastas; fotos, música e pastas do sistema ficam de fora. Na primeira vez, o Android pede o “acesso a todos os arquivos”: ligue a opção para o PKHeX Modern e volte ao app. Os saves aparecem agrupados por emulador e são lidos e gravados no arquivo original, com backup antes de gravar. Feche o jogo no emulador antes de salvar no app."),
            new("Arquivos no Android", "Abra saves e ZIPs pelo seletor do sistema. Salvar grava no original com backup privado e verifica os bytes gravados; se o original mudar em outro app, a sobrescrita é bloqueada. Salvar como exporta uma cópia. Saves importados, Bank e backups ficam no armazenamento privado e são removidos ao desinstalar."),
            new("Animação da atualização", "Enquanto a versão nova baixa, um painel mostra Pokébolas cinzas que ganham cor conforme o download avança, cada uma de um tipo, até a Master Ball nos 100%, com a equipe do save aberto andando em fila sobre a barra (sem save, um inicial aleatório; às vezes um deles aparece shiny). “Continuar usando” esconde o painel e o download segue, com o progresso na barra lateral. Em Ajuda › Sobre, “✨ Ver animação” mostra a animação sem baixar nada."),
            new("Atualização no Android", "Ao abrir, o app verifica se saiu uma versão nova. Ao confirmar em “Atualizar agora”, baixa o APK da release, confere o arquivo e abre o instalador do Android; na primeira vez, o Android pede para permitir instalar apps do PKHeX Modern. A instalação é por cima, sem perder saves, Bank e preferências. A verificação pode ser desligada em Ajuda › Sobre."),
            new("Pasta de saves no Android", "Na página Saves, “Escolher pasta...” abre o seletor do Android: escolha a pasta onde ficam seus saves. O app lê a pasta inteira, com subpastas, e mostra os saves como no desktop; “Atualizar” e a abertura do app trazem o que mudou. Abrir um save e tocar em Salvar grava de volta no arquivo da pasta, com backup. Um save aberto ou com alterações não salvas não é trocado pela versão da pasta."),
            new("Bank em pasta externa no Android", "No Bank, “Adicionar pasta” abre o seletor do Android: escolha uma pasta com arquivos .pk* (por exemplo, a de outro app ou uma pasta sincronizada). O app guarda uma cópia dela e sincroniza: ao abrir, traz o que mudou na pasta; cada Pokémon gravado ou apagado no Bank vai para a pasta na hora. Se o mesmo arquivo mudou no app e fora dele, fica a versão da pasta e a do app vai para os backups. Remover a pasta da lista não apaga nada nela."),
            new("Tela e toque", "A interface é a mesma do desktop, com a tela deitada e em tela cheia (deslize da borda para ver as barras do Android por um momento); em celulares tudo é reduzido para caber. Toque num slot para editar. O botão Voltar do Android fecha a pergunta aberta ou volta como o Esc. Teclados externos aceitam os mesmos atalhos do desktop."),
        ]),
    ];
}
